/** Local domain contracts, not new database columns or assumed Supabase payloads. */
export interface ReviewEvidence {
  matchId: string;
  /** Fingerprint of the sporting input reviewed, generated by the trusted adapter. */
  basis: string;
  goals: { complete: boolean; documentReference: string | null; confirmedAt: string | null };
  cards: { complete: boolean; documentReference: string | null; confirmedAt: string | null };
}
export interface ProtestEvidence {
  id: string;
  matchIds: readonly string[];
  affectsGroupClassification: boolean;
  status: "open" | "resolved";
  resolution?: { id: string; documentReference: string; notifiedAt: string };
}
export interface PublicationApproval {
  id: string;
  scope: "group-classification";
  basis: string;
  documentReference: string;
  notifiedAt: string;
}
export interface CompetitionEvidence {
  reviews: readonly ReviewEvidence[];
  protests: readonly ProtestEvidence[];
  /** Trusted reader completed the protest register; [] alone is not proof of absence. */
  protestsComplete: boolean;
  approval?: PublicationApproval;
}
export type PublicationBlocker = "results_pending" | "ranking_pending" | "certification_pending" | "protests_unverified" |
  "protest_pending" | "approval_missing" | "approval_stale";
export interface ClassificationPublication {
  scope: "group-classification";
  status: "pending" | "provisional" | "official";
  basis: string;
  blockers: PublicationBlocker[];
  approvalId: string | null;
  /** A mathematically determined order is not an approval by the Committee. */
  calculationComplete: boolean;
}
